import type { Insight, InsightBlock, InsightCategory } from "./insights"

interface Seed {
  slug: string
  title: string
  seoTitle?: string
  description: string
  category: InsightCategory
  answer: string
  sections: Array<[string, string]>
  takeaways: string[]
  callout: [string, string]
  services: string[]
  work?: string[]
  related?: string[]
  author?: "rhys" | "trevor-newton-bradley"
  featured?: boolean
  heroImage?: Insight["heroImage"]
}

function article(seed: Seed, priority: number): Insight {
  const body: InsightBlock[] = [
    { type: "paragraph", text: seed.answer },
    ...seed.sections.flatMap(([heading, text]) => [{ type: "heading" as const, text: heading }, { type: "paragraph" as const, text }]),
    { type: "heading", text: "A practical way to decide" },
    { type: "list", items: seed.takeaways },
    { type: "callout", title: seed.callout[0], text: seed.callout[1] },
  ]
  return {
    slug: seed.slug,
    title: seed.title,
    seoTitle: seed.seoTitle,
    description: seed.description,
    status: "published",
    authorSlug: seed.author ?? "rhys",
    category: seed.category,
    datePublished: "2026-09-23",
    dateModified: "2026-09-23",
    heroImage: seed.heroImage,
    body,
    brief: {
      targetQuery: seed.title,
      searchIntent: seed.description,
      angle: seed.answer,
      outline: seed.sections.map(([heading]) => heading),
      firstHandEvidence: seed.work?.length ? [`ScaleSmiths work: ${seed.work.join(", ")}`] : ["ScaleSmiths delivery practice and repository-backed service model"],
      priority,
    },
    relatedServices: seed.services,
    relatedCaseStudies: seed.work ?? [],
    relatedInsights: seed.related,
    featured: seed.featured,
  }
}

